mapper.update:
update
    t_lock_massage
set status = true
where is_deleted = 0
  and group_id = #{lockMassageDto.groupId}
  and element_id = #{lockMassageDto.elementId}
  and process_id = #{lockMassageDto.processId}
  and room_id = #{lockMassageDto.roomId}
  and round = #{lockMassageDto.round}
  and is_preview = #{previewStatus}
  and user_id = #{lockMassageDto.userId}
  and lock_reason = #{workId}

mapper.select:
select *
from t_lock_massage
where is_deleted = 0
  and group_id = #{lockMassageDto.groupId}
  and element_id = #{lockMassageDto.elementId}
  and process_id = #{lockMassageDto.processId}
  and room_id = #{lockMassageDto.roomId}
  and round = #{lockMassageDto.round}
  and role_name = #{lockMassageDto.roleName}
  and work_id = #{lockMassageDto.workId}
  and is_preview = #{previewStatus}
order by create_date desc
